/* Local group analytics: topic counters only; no question text or chat logs. */
const VISIT_TOPICS={cooking:'Кухня',pattern:'Наряды и узоры',language:'Язык',dialogue:'Разговоры',legend:'Легенда'};
let visitTeacherSession=false,visitTimer=null;
function visitAnalytics(u){if(!u)return null;const a=u.visitAnalytics;if(!a||a.version!==1)u.visitAnalytics={version:1,regions:[],scenes:[],completedScenes:[],timeMs:0,sceneTime:{},errors:{},questions:{},legendRead:false,startedAt:null,lastAt:null};return u.visitAnalytics}
function visitTopic(value){const v=String(value||'dialogue').toLowerCase();return ({recipe:'cooking',cook:'cooking',recipes:'cooking',puzzle:'pattern',outfit:'pattern',outfits:'pattern',word:'language',words:'language',grandma:'dialogue',epic:'legend'})[v]|| (Object.hasOwn(VISIT_TOPICS,v)?v:'dialogue')}
function visitTickTime(u,force=false){if(!visitTimer||u&&visitTimer.id!==u.id)return;const t=visitTimer,now=Date.now();visitTimer.at=now;const owner=db.users.find(v=>v.id===t.id);if(!owner||(!force&&(document.visibilityState==='hidden'||t.paused)))return;const elapsed=Math.min(60000,Math.max(0,now-t.previous));t.previous=now;if(now-t.activity>120000)return;const a=visitAnalytics(owner);a.timeMs+=elapsed;a.sceneTime[t.scene]=(a.sceneTime[t.scene]||0)+elapsed;a.lastAt=new Date(now).toISOString();save()}
function visitFlushTime(u){visitTickTime(u);if(!u||visitTimer?.id===u.id)visitTimer=null}
function visitTrackScene(u,step){if(!u)return;visitFlushTime();const scene=String(step),a=visitAnalytics(u),now=Date.now();if(!a.scenes.includes(scene))a.scenes.push(scene);if(!a.regions.includes('bashkortostan'))a.regions.push('bashkortostan');a.startedAt=a.startedAt||new Date(now).toISOString();a.lastAt=new Date(now).toISOString();visitTimer={id:u.id,scene,at:now,previous:now,activity:now};save()}
function visitRecord(u,event,data={}){if(!u)return;const a=visitAnalytics(u),topic=visitTopic(data.topic||data.category||data.kind),now=Date.now();if(visitTimer?.id===u.id)visitTimer.activity=now;a.startedAt=a.startedAt||new Date(now).toISOString();a.lastAt=new Date(now).toISOString();if(['error','mistake','wrong','cookError','patternError','languageError'].includes(event)){const key=event==='cookError'?'cooking':event==='patternError'?'pattern':event==='languageError'?'language':topic;a.errors[key]=(a.errors[key]||0)+1}else if(['question','ask','chatQuestion'].includes(event))a.questions[topic]=(a.questions[topic]||0)+1;else if(['complete','sceneComplete','scene_completed'].includes(event)){const scene=String(data.scene??data.step??visitTimer?.scene??'unknown');if(!a.completedScenes.includes(scene))a.completedScenes.push(scene)}else if(['legendRead','legend_read','epicRead'].includes(event))a.legendRead=true;else if(['region','regionEnter'].includes(event)){const region=String(data.region||'bashkortostan');if(!a.regions.includes(region))a.regions.push(region)}else if(event==='finish'){if(!a.regions.includes('bashkortostan'))a.regions.push('bashkortostan');a.finishedAt=a.finishedAt||new Date(now).toISOString()}save()}
if(typeof document!=='undefined'){document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){visitTickTime(null,true);if(visitTimer)visitTimer.paused=true}else if(visitTimer){visitTimer.paused=false;visitTimer.previous=Date.now();visitTimer.activity=Date.now()}});document.addEventListener('pointerdown',()=>{if(visitTimer)visitTimer.activity=Date.now()},{passive:true});document.addEventListener('keydown',()=>{if(visitTimer)visitTimer.activity=Date.now()});}
if(typeof window!=='undefined'){window.addEventListener('pagehide',()=>visitFlushTime());setInterval(()=>visitTickTime(),15000)}
function visitTeacherActive(){try{return sessionStorage.getItem('ethnohod-local-teacher')==='1'||visitTeacherSession}catch{return visitTeacherSession}}
function visitTeacherNotice(){return '<p class="notice">Демонстрационный кабинет работает без пароля. Группы, коды и прогресс хранятся только в этом браузере. Для демо используйте вымышленные ники.</p>'}
function visitTeacherGate(){return `<div class="game-world"><section class="game-panel"><h2>Организуйте путешествие для группы</h2><p>Создайте группу для тура или экскурсии, получите код приглашения и отслеживайте, как участники проходят интерактивный маршрут.</p>${visitTeacherNotice()}<button type="button" class="kid-primary" id="visitTeacherEnter">Открыть локальный кабинет ${kidIcon('arrow')}</button></section></div>`}
const VISIT_TOUR_FORMATS={intro:'Знакомство с регионом',before:'Подготовка к поездке',after:'После экскурсии',custom:'Свой формат'};
function visitContext(group){
  const {context,customContext}=group.assignment||{};
  if(context==='custom')return customContext||VISIT_TOUR_FORMATS.custom;
  return Object.hasOwn(VISIT_TOUR_FORMATS,context)?VISIT_TOUR_FORMATS[context]:context||'Формат не выбран';
}
function visitSnapshot(u){const a=u.visitAnalytics,s=u.story||{},has=!!a;const recipes=Object.values(s.cooking||{}).filter(x=>Array.isArray(x)&&x.length===3).length,outfits=Object.values(s.outfits||{}).filter(x=>Array.isArray(x)&&x.length===3).length;let completed=new Set(a?.completedScenes||[]);if(recipes>=3)completed.add('2');if(outfits>=2)completed.add('3');if(s.words?.length>=5)completed.add('4');if(s.grandma?.length>=4)completed.add('5');if(s.completed)completed.add('7');if(visitRoomsComplete(s))completed.add('8');const scenes=has?a.scenes.length:s.completed?STORY_ORDER.length-(visitRoomsComplete(s)?0:1):s.step>0?storyStepIndex(s)+1:0;return {u,regions:(a?.regions?.length||((s.step>0||s.completed||u.completed?.length)?1:0)),scenes,completed:completed.size,time:has?a.timeMs:null,errors:a?.errors||{},questions:a?.questions||{},legend:!!a?.legendRead||!!s.legendRead,finished:!!s.completed||!!a?.finishedAt,started:!!a?.startedAt||s.step>0||!!s.completed,tracked:has}}
function visitTotal(o){return Object.values(o||{}).reduce((a,b)=>a+(Number(b)||0),0)}
function visitDuration(ms){if(ms==null)return 'Не измерялось';if(ms<60000)return Math.floor(ms/1000)+' с';return Math.floor(ms/60000)+' мин '+Math.floor(ms%60000/1000)+' с'}
function visitTeacherPage(){if(!visitTeacherActive())return visitTeacherGate();const students=db.users.filter(u=>u.code&&db.classes.some(c=>c.code===u.code)).map(visitSnapshot),finished=students.filter(s=>s.finished).length;return `<div class="game-world">${visitTeacherNotice()}<div class="game-stats game-profile-stats"><div><strong>${db.classes.length}</strong><span>туристических групп</span></div><div><strong>${students.length}</strong><span>участников</span></div><div><strong>${finished}</strong><span>завершённых историй</span></div></div><div class="grid"><section class="game-panel"><h2>Создать группу</h2><form id="visitClassCreate"><label for="visitClassName">Название группы</label><input id="visitClassName" name="name" required maxlength="40" placeholder="Например, Южный Урал — 12 июня"><button type="submit" class="kid-primary">Создать и получить код ${kidIcon('arrow')}</button><p id="visitTeacherError" role="alert" class="error"></p></form></section><section class="game-panel"><h2>Как подключить группу</h2><ol><li>Создайте группу и выберите формат прохождения маршрута.</li><li>Передайте участнику код для входа в этом браузере.</li><li>Откройте отчёт группы, чтобы посмотреть прогресс и темы вопросов.</li></ol></section></div><h2>Ваши группы</h2><div class="grid">${db.classes.map(c=>`<article class="game-panel"><h3>${esc(c.name)}</h3><p>Код: <strong>${esc(c.code)}</strong></p><p>Участников: ${db.users.filter(u=>u.code===c.code).length} · ${esc(visitContext(c))}</p>${link('group/'+encodeURIComponent(c.code),'Маршрут и прогресс '+kidIcon('arrow'))}</article>`).join('')}</div><button type="button" class="btn secondary" id="visitTeacherExit">Выйти из кабинета</button></div>`}
function wireVisitTeacher(){const enter=document.getElementById('visitTeacherEnter');if(enter){enter.onclick=()=>{visitTeacherSession=true;try{sessionStorage.setItem('ethnohod-local-teacher','1')}catch{}render()};return}const exit=document.getElementById('visitTeacherExit');if(exit)exit.onclick=()=>{visitTeacherSession=false;try{sessionStorage.removeItem('ethnohod-local-teacher')}catch{}render()};const form=document.getElementById('visitClassCreate');if(form)form.onsubmit=e=>{e.preventDefault();const name=String(new FormData(form).get('name')||'').trim();if(!name){document.getElementById('visitTeacherError').textContent='Введите название группы.';return}let code;do{const random=new Uint32Array(1);crypto.getRandomValues(random);code='E'+random[0].toString(36).slice(0,5).toUpperCase().padEnd(5,'0')}while(db.classes.some(c=>c.code===code));db.classes.push({name,code,region:'Башкортостан',assignment:{region:'bashkortostan',context:'intro',customContext:'',assignedAt:new Date().toISOString()}});save();location.hash='group/'+code}}
function visitClassPage(code){if(!visitTeacherActive())return visitTeacherGate();const c=db.classes.find(c=>c.code===decodeURIComponent(code));if(!c)return `<div class="game-world"><section class="game-panel"><h2>Группа не найдена</h2>${link('organizer','К вашим группам')}</section></div>`;const rows=db.users.filter(u=>u.code===c.code).map(visitSnapshot),a=c.assignment||{};const total=rows.length,finished=rows.filter(r=>r.finished).length,measured=rows.filter(r=>r.time!=null),time=measured.reduce((s,r)=>s+r.time,0);return `<div class="game-world">${link('organizer','← Все группы',true)}${visitTeacherNotice()}<section class="game-panel"><h2>${esc(c.name)}</h2><p>Код приглашения: <strong>${esc(c.code)}</strong></p><form id="visitAssignment"><label for="visitRegion">Маршрут группы</label><select id="visitRegion" name="region"><option value="bashkortostan">Башкортостан · В гостях у Данияра</option></select><label for="visitContext">Формат прохождения</label><select id="visitContext" name="context">${Object.entries(VISIT_TOUR_FORMATS).map(([value,label])=>`<option value="${value}" ${a.context===value?'selected':''}>${label}</option>`).join('')}${a.context&&!Object.hasOwn(VISIT_TOUR_FORMATS,a.context)?`<option value="${esc(a.context)}" selected>${esc(a.context)} (сохранённая пометка)</option>`:''}</select><label for="visitCustomContext">Название своего формата</label><input id="visitCustomContext" name="customContext" value="${esc(a.customContext||'')}" maxlength="100" placeholder="Например, Дополнение к экскурсии по Уфе"><button class="kid-primary" type="submit">Сохранить настройки группы</button><p id="visitAssignmentStatus" role="status"></p></form><p>Формат помогает организатору отметить, как группа использует маршрут. Эта пометка видна в кабинете и в отчёте.</p></section><div class="game-stats game-profile-stats"><div><strong>${finished} / ${total}</strong><span>завершили историю</span></div><div><strong>${rows.reduce((s,r)=>s+visitTotal(r.errors),0)}</strong><span>ошибок в заданиях</span></div><div><strong>${measured.length?visitDuration(time):'—'}</strong><span>времени в сценах суммарно</span></div></div><section class="game-panel"><h2>Прогресс участников</h2><p>По отчёту видно, где остановились участники и какие темы вызвали вопросы. Время учитывает активное прохождение. В отчёт попадает число вопросов по темам.</p>${rows.length?`<div style="overflow-x:auto"><table><thead><tr><th>Участник</th><th>Регионов</th><th>Сцены</th><th>Время</th><th>Ошибки</th><th>Вопросы</th><th>Легенда</th><th>История</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.u.nick)}${r.u.rewards?.includes('kurai')?'<span class="visit-teacher-badge" title="Значок Курай получен">🎖 Курай</span>':''}</td><td>${r.regions}</td><td>${r.completed} завершено / ${r.scenes} открыто</td><td>${visitDuration(r.time)}</td><td>${r.tracked?visitTotal(r.errors):'Не измерялось'}</td><td>${r.tracked?visitTotal(r.questions):'Не измерялось'}</td><td>${r.legend?'Прочитана':'Не отмечена'}</td><td>${r.finished?'Завершена':r.started?'В процессе':'Не начата'}</td></tr>`).join('')}</tbody></table></div><div class="game-actions"><button type="button" class="btn secondary" id="visitCSV">Скачать CSV</button><button type="button" class="btn secondary" id="visitPrint">Печать / PDF</button></div>${rows.map(r=>`<details class="story-sources"><summary>${esc(r.u.nick)} — ошибки и вопросы по темам</summary><table><thead><tr><th>Тема</th><th>Ошибки</th><th>Вопросы</th></tr></thead><tbody>${Object.entries(VISIT_TOPICS).map(([key,label])=>`<tr><td>${label}</td><td>${r.tracked?r.errors[key]||0:'—'}</td><td>${r.tracked?r.questions[key]||0:'—'}</td></tr>`).join('')}</tbody></table>${visitSceneBreakdown(r)}</details>`).join('')}`:'<div class="game-empty"><p>В группе пока нет участников. Профили появятся после входа по коду группы в этом браузере.</p></div>'}</section></div>`}
function visitCSVCell(v){const text=String(v??''),safe=/^[\s]*[=+@-]/.test(text)?"'"+text:text;return '"'+safe.replace(/"/g,'""')+'"'}
function wireVisitClass(code){if(!visitTeacherActive()){wireVisitTeacher();return}const c=db.classes.find(c=>c.code===decodeURIComponent(code));if(!c)return;const form=document.getElementById('visitAssignment');if(form)form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),context=String(f.get('context')||'intro'),custom=String(f.get('customContext')||'').trim();if(context==='custom'&&!custom){document.getElementById('visitAssignmentStatus').textContent='Укажите название своего формата.';return}c.assignment={region:'bashkortostan',context:Object.hasOwn(VISIT_TOUR_FORMATS,context)||context===c.assignment?.context?context:'intro',customContext:custom,assignedAt:new Date().toISOString()};save();document.getElementById('visitAssignmentStatus').textContent='Настройки группы сохранены. Формат: '+visitContext(c)};const print=document.getElementById('visitPrint');if(print)print.onclick=()=>{const panels=[...document.querySelectorAll('.story-sources')],states=panels.map(d=>d.open);panels.forEach(d=>d.open=true);window.addEventListener('afterprint',()=>panels.forEach((d,i)=>d.open=states[i]),{once:true});window.print()};const csv=document.getElementById('visitCSV');if(csv)csv.onclick=()=>{visitTickTime();const students=db.users.filter(u=>u.code===c.code).map(visitSnapshot),headers=['Группа','Код группы','Формат прохождения','Ник участника','Регионов','Сцен открыто','Сцен завершено','Время (секунды)','История завершена','Легенда прочитана',...Object.values(VISIT_TOPICS).map(t=>'Ошибки: '+t),...Object.values(VISIT_TOPICS).map(t=>'Вопросы: '+t)],lines=[headers,...students.map(r=>[c.name,c.code,visitContext(c),r.u.nick,r.regions,r.scenes,r.completed,r.time==null?'Не измерялось':Math.floor(r.time/1000),r.finished?'да':'нет',r.legend?'да':'нет',...Object.keys(VISIT_TOPICS).map(k=>r.tracked?r.errors[k]||0:'Не измерялось'),...Object.keys(VISIT_TOPICS).map(k=>r.tracked?r.questions[k]||0:'Не измерялось')])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(r=>r.map(visitCSVCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download='ethnohod-group-'+c.code+'.csv';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}

function visitSceneBreakdown(row){const a=row.u.visitAnalytics;if(!a?.scenes?.length)return '<p>Для старого прохождения подробное время сцен не измерялось.</p>';return '<h3>Время по сценам</h3><table><thead><tr><th>Сцена</th><th>Время</th><th>Статус</th></tr></thead><tbody>'+a.scenes.map(id=>{const n=Number(id),name=typeof STORY_STEPS!=='undefined'&&Number.isInteger(n)&&STORY_STEPS[n]?STORY_STEPS[n]:String(id);return '<tr><td>'+esc(name)+'</td><td>'+visitDuration(a.sceneTime[id]||0)+'</td><td>'+(a.completedScenes.includes(id)?'Завершена':'Открыта')+'</td></tr>'}).join('')+'</tbody></table>'}
